head.b:skin:
:root{--ink:#111318;--muted:#737986;--paper:#f3f1ec;--card:#fff;--line:rgba(17,19,24,.10);--accent:#1f5eff;--radius:28px;--shadow:0 18px 55px rgba(17,19,24,.10)}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font-family:Inter,Arial,sans-serif;line-height:1.65}a{color:inherit;text-decoration:none}img{max-width:100%;height:auto}.wrap{width:min(1320px,96%);margin:auto}
.header{position:fixed;top:18px;left:0;right:0;z-index:50;background:transparent}.nav{min-height:62px;padding:8px 18px 8px 12px;background:rgba(255,255,255,.91);border:1px solid rgba(255,255,255,.75);border-radius:22px;display:flex;align-items:center;justify-content:space-between;gap:24px;box-shadow:0 12px 35px rgba(0,0,0,.08);backdrop-filter:blur(16px)}.brand{display:flex;align-items:center;gap:10px;font-weight:900;font-size:20px;letter-spacing:-.5px}.mark{width:42px;height:42px;border-radius:11px;background:#0c0d10;color:#fff;display:grid;place-items:center;font-size:19px}.menu{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.menu a{padding:10px 9px;font-size:13px;font-weight:800;letter-spacing:1.3px;text-transform:uppercase;color:#686e7b;position:relative}.menu a:after{content:'';position:absolute;left:9px;right:9px;bottom:5px;height:2px;background:#111;transform:scaleX(0);transform-origin:left;transition:transform .28s ease}.menu a:hover{color:#111}.menu a:hover:after{transform:scaleX(1)}
.hero{min-height:100vh;padding:130px 0 42px;display:flex;align-items:center;position:relative;overflow:hidden;background:linear-gradient(115deg,rgba(16,18,23,.80),rgba(16,18,23,.52)),radial-gradient(circle at 82% 18%,rgba(255,255,255,.18),transparent 24%),linear-gradient(135deg,#777d87,#b8b8b5)}.hero:before{content:'∫   π   √x   Σ   f(x)';position:absolute;right:-2%;top:19%;font-family:Georgia,serif;font-size:clamp(70px,10vw,150px);font-style:italic;color:rgba(255,255,255,.06);transform:rotate(-7deg);white-space:nowrap;animation:floatMath 9s ease-in-out infinite}.hero:after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,rgba(255,255,255,.035) 1px,transparent 1px),linear-gradient(rgba(255,255,255,.035) 1px,transparent 1px);background-size:54px 54px;mask-image:linear-gradient(to right,transparent,black 40%,black)}.hero-inner{position:relative;z-index:2;color:#fff;padding:4vh 0 0}.eyebrow{display:inline-flex;border:1px solid rgba(255,255,255,.28);border-radius:999px;padding:7px 17px;font-size:11px;font-weight:700;letter-spacing:4px;text-transform:uppercase;animation:fadeUp .8s both}.hero h1{margin:28px 0 18px;font-size:clamp(64px,10vw,142px);line-height:.78;letter-spacing:-7px;font-weight:900;text-transform:uppercase;max-width:980px;animation:fadeUp .9s .08s both}.hero h1 em{display:block;font-family:Georgia,'Times New Roman',serif;font-size:.72em;font-weight:400;text-transform:none;letter-spacing:-4px;margin-left:11%;margin-top:18px}.hero p{max-width:760px;color:rgba(255,255,255,.80);font-size:clamp(16px,1.5vw,21px);letter-spacing:.2px;animation:fadeUp .9s .18s both}.actions{display:flex;gap:18px;align-items:center;flex-wrap:wrap;margin-top:30px;animation:fadeUp .9s .28s both}.btn{display:inline-flex;align-items:center;gap:18px;padding:13px 18px;border-radius:999px;background:#fff;color:#111;font-size:14px;font-weight:900;letter-spacing:1.1px;text-transform:uppercase;transition:.3s}.btn:hover{transform:translateY(-3px);box-shadow:0 14px 30px rgba(0,0,0,.18)}.btn.alt{background:rgba(255,255,255,.11);color:#fff;border:1px solid rgba(255,255,255,.16)}.arrow{font-size:22px;transition:transform .25s}.btn:hover .arrow{transform:translateX(5px)}.scroll-note{position:absolute;z-index:3;bottom:28px;left:50%;transform:translateX(-50%);color:rgba(255,255,255,.48);font-size:10px;font-weight:700;letter-spacing:5px;text-transform:uppercase}.scroll-note:before{content:'';display:block;width:1px;height:48px;background:rgba(255,255,255,.32);margin:0 auto 10px;animation:scrollLine 1.8s ease-in-out infinite}
.section{padding:72px 0}.section-head{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:28px}.section h2{font-size:clamp(32px,4vw,54px);line-height:1;letter-spacing:-2px;margin:0}.section-head p{margin:8px 0 0;color:var(--muted)}.levels{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.level{min-height:310px;background:var(--card);border:1px solid var(--line);border-radius:26px;padding:28px;box-shadow:var(--shadow);position:relative;overflow:hidden;transition:transform .35s,box-shadow .35s}.level:before{content:'';position:absolute;width:180px;height:180px;border-radius:50%;right:-80px;top:-80px;background:rgba(31,94,255,.08);transition:.4s}.level:hover{transform:translateY(-8px);box-shadow:0 26px 70px rgba(17,19,24,.14)}.level:hover:before{transform:scale(1.4)}.badge{display:inline-block;border:1px solid var(--line);padding:6px 11px;border-radius:999px;font-size:11px;font-weight:900;letter-spacing:2px}.level h3{font-size:26px;line-height:1.1;margin:52px 0 12px}.level p{color:var(--muted)}.go{position:absolute;left:28px;bottom:26px;font-weight:800}.resources{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}.resource{background:#17191e;color:#fff;border-radius:22px;padding:24px;min-height:150px;transition:.3s}.resource:hover{transform:translateY(-6px)}.resource b{display:block;font-size:18px;margin-bottom:8px}.resource span{font-size:14px;color:#aeb3bd}
.content-grid{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:28px}.mainbox,.sidebox{background:#fff;border:1px solid var(--line);border-radius:22px;padding:24px}.sidebox{margin-bottom:18px}.sidebox h3{margin-top:0}.post-outer{border-bottom:1px solid var(--line);padding-bottom:25px;margin-bottom:25px}.post-title,.post-title a{font-size:29px;line-height:1.2}.post-body{font-size:16px}.post-body h2,.post-body h3{margin-top:30px}.post-body table{width:100%;border-collapse:collapse}.post-body th,.post-body td{border:1px solid var(--line);padding:10px}.post-body blockquote{margin:20px 0;border-left:4px solid var(--accent);background:#f5f7fb;padding:14px 18px}.post-labels a{display:inline-block;background:#eef2ff;color:#1748c9;padding:5px 9px;border-radius:999px;margin:4px;font-size:12px}.date-header{color:var(--muted);font-size:13px}.footer{margin-top:55px;background:#111318;color:#c5c8d0;padding:52px 0 24px}.footer-grid{display:grid;grid-template-columns:2fr 1fr 1fr;gap:30px}.footer h3{color:#fff}.footer a{display:block;margin:7px 0}.copy{border-top:1px solid rgba(255,255,255,.1);margin-top:30px;padding-top:18px;font-size:13px;color:#7f8490}.mobile{display:none;border:0;background:#f0f1f3;border-radius:10px;padding:9px 11px;font-size:18px}

.footer-shell{padding:18px 0 28px;background:var(--paper)}.footer{width:min(1320px,96%);margin:0 auto;background:rgba(17,19,24,.98);color:#c5c8d0;padding:44px 38px 22px;border-radius:30px;box-shadow:0 24px 70px rgba(17,19,24,.18);position:relative;overflow:hidden}.footer:before{content:'π  ∫  √  Σ';position:absolute;right:-20px;top:-42px;font-family:Georgia,serif;font-size:92px;color:rgba(255,255,255,.035);letter-spacing:15px;transform:rotate(-8deg)}.footer-grid{position:relative;z-index:1;display:grid;grid-template-columns:1.7fr 1fr 1fr 1.15fr;gap:34px}.footer h3{color:#fff;margin:0 0 15px;font-size:15px;letter-spacing:1.4px;text-transform:uppercase}.footer-brand{font-size:28px!important;letter-spacing:-1px!important;text-transform:none!important}.footer p{max-width:440px}.footer a{display:block;margin:8px 0;transition:.25s}.footer a:hover{color:#fff;transform:translateX(4px)}.socials{display:flex;gap:9px;flex-wrap:wrap;margin-top:18px}.socials a{width:42px;height:42px;margin:0;border:1px solid rgba(255,255,255,.14);border-radius:13px;display:grid;place-items:center;color:#fff;font-size:12px;font-weight:900;letter-spacing:.5px}.socials a:hover{background:#fff;color:#111;transform:translateY(-3px)}.wa-btn{display:inline-flex!important;align-items:center;gap:9px;margin-top:13px!important;padding:10px 14px;border-radius:999px;background:#fff;color:#111!important;font-weight:800}.wa-btn:hover{transform:translateY(-2px)!important}.copy{position:relative;z-index:1;border-top:1px solid rgba(255,255,255,.1);margin-top:30px;padding-top:18px;font-size:13px;color:#7f8490;display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}.footer-mini{display:flex;gap:18px;flex-wrap:wrap}.footer-mini a{margin:0}.floating-wa{position:fixed;right:22px;bottom:22px;z-index:60;width:58px;height:58px;border-radius:50%;background:#fff;color:#111;display:grid;place-items:center;font-size:14px;font-weight:900;box-shadow:0 15px 40px rgba(0,0,0,.18);border:1px solid rgba(17,19,24,.08);transition:.3s}.floating-wa:hover{transform:translateY(-4px) scale(1.04)}
.reveal{opacity:0;transform:translateY(28px);transition:opacity .7s ease,transform .7s ease}.reveal.visible{opacity:1;transform:none}@keyframes fadeUp{from{opacity:0;transform:translateY(30px)}to{opacity:1;transform:none}}@keyframes floatMath{0%,100%{transform:translateY(0) rotate(-7deg)}50%{transform:translateY(24px) rotate(-4deg)}}@keyframes scrollLine{0%,100%{transform:scaleY(.35);transform-origin:top}50%{transform:scaleY(1);transform-origin:top}}
@media(max-width:900px){.footer-grid{grid-template-columns:1fr 1fr}.footer{padding:34px 26px 20px;border-radius:24px}.floating-wa{right:15px;bottom:15px;width:54px;height:54px}.header{top:10px}.wrap{width:min(94%,1320px)}.mobile{display:block}.menu{display:none;position:absolute;top:72px;left:3%;right:3%;background:#fff;border-radius:18px;padding:12px;box-shadow:var(--shadow)}.menu.open{display:grid}.menu a{color:#555}.hero{min-height:92vh;padding-top:115px}.hero h1{letter-spacing:-4px}.hero h1 em{margin-left:4%}.levels{grid-template-columns:1fr}.resources{grid-template-columns:1fr 1fr}.content-grid{grid-template-columns:1fr}.footer-grid{grid-template-columns:1fr}.scroll-note{display:none}}@media(max-width:560px){.footer-grid{grid-template-columns:1fr}.footer{width:94%;padding:30px 22px 18px}.copy{display:block}.footer-mini{margin-top:10px}.hero h1{font-size:58px;letter-spacing:-3px}.hero h1 em{font-size:.72em;margin-top:13px}.eyebrow{letter-spacing:2px}.resources{grid-template-columns:1fr}.section{padding:52px 0}.nav{border-radius:18px}.brand{font-size:18px}}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important;scroll-behavior:auto!important}.reveal{opacity:1;transform:none}}

.about-contact{padding:72px 0 20px}.about-contact-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.info-panel{background:#fff;border:1px solid var(--line);border-radius:28px;padding:34px;box-shadow:0 18px 55px rgba(17,19,24,.06)}.info-panel .kicker{display:inline-block;font-size:11px;font-weight:900;letter-spacing:2.5px;text-transform:uppercase;color:#777;margin-bottom:12px}.info-panel h2{font-size:clamp(30px,4vw,52px);letter-spacing:-2px;margin:0 0 14px}.info-panel p{font-size:16px;line-height:1.8;color:#686e7b}.contact-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.contact-actions a{display:inline-flex;align-items:center;gap:9px;padding:12px 16px;border-radius:999px;border:1px solid var(--line);font-weight:800}.contact-actions a:hover{transform:translateY(-2px);box-shadow:0 10px 25px rgba(0,0,0,.08)}.socials svg,.floating-wa svg,.wa-btn svg{width:20px;height:20px;fill:currentColor}.socials a{font-size:0}.floating-wa{font-size:0}.socials a.whatsapp:hover,.floating-wa:hover{background:#25D366;color:#fff;border-color:#25D366}.socials a.facebook:hover{background:#1877F2;color:#fff;border-color:#1877F2}.socials a.instagram:hover{background:#E4405F;color:#fff;border-color:#E4405F}.socials a.pinterest:hover{background:#E60023;color:#fff;border-color:#E60023}.socials a.youtube:hover{background:#FF0000;color:#fff;border-color:#FF0000}@media(max-width:900px){.about-contact-grid{grid-template-columns:1fr}.about-contact{padding-top:50px}}

.post-footer-contact{max-width:1180px;margin:24px auto 36px;padding:0 18px}.post-footer-contact .info-panel{margin:0;border-radius:32px;text-align:center}.post-footer-contact .contact-actions{justify-content:center;flex-wrap:wrap}

.prefooter-info{padding:78px 0 30px;background:var(--paper)}
.prefooter-grid{display:grid;grid-template-columns:1.15fr .85fr;gap:22px;align-items:stretch}
.about-prof{background:#fff;border:1px solid var(--line);border-radius:30px;overflow:hidden;display:grid;grid-template-columns:.88fr 1.12fr;min-height:430px;box-shadow:0 20px 60px rgba(17,19,24,.07)}
.prof-photo{position:relative;min-height:430px;background:#e9edf2;overflow:hidden}
.prof-photo img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .7s cubic-bezier(.2,.7,.2,1)}
.about-prof:hover .prof-photo img{transform:scale(1.045)}
.prof-photo:after{content:'';position:absolute;inset:0;background:linear-gradient(180deg,transparent 55%,rgba(0,0,0,.22))}
.prof-badge{position:absolute;left:18px;bottom:18px;z-index:2;background:rgba(255,255,255,.92);backdrop-filter:blur(12px);padding:9px 13px;border-radius:999px;font-size:12px;font-weight:900;color:#111}
.about-copy{padding:38px;display:flex;flex-direction:column;justify-content:center}
.about-copy .kicker,.contact-card .kicker{display:inline-block;font-size:11px;font-weight:900;letter-spacing:2.5px;text-transform:uppercase;color:#777;margin-bottom:12px}
.about-copy h2,.contact-card h2{font-size:clamp(30px,4vw,50px);letter-spacing:-2px;margin:0 0 15px;line-height:1.02}
.about-copy p,.contact-card p{font-size:16px;line-height:1.8;color:#686e7b}
.contact-card{background:#111318;color:#fff;border-radius:30px;padding:38px;box-shadow:0 20px 60px rgba(17,19,24,.12);position:relative;overflow:hidden;display:flex;flex-direction:column;justify-content:center}
.contact-card:before{content:'@  +  π';position:absolute;right:-12px;top:-24px;font-family:Georgia,serif;font-size:78px;color:rgba(255,255,255,.045);transform:rotate(-8deg)}
.contact-card .kicker{color:#9da3ae}.contact-card h2{color:#fff}.contact-card p{color:#b9bec8;position:relative;z-index:1}
.contact-card .contact-actions{position:relative;z-index:1}.contact-card .contact-actions a{background:#fff;color:#111;border-color:#fff}.contact-card .contact-actions a:hover{background:#f1f1f1}
.contact-detail{margin-top:20px;display:grid;gap:10px;position:relative;z-index:1}.contact-detail a{display:flex;align-items:center;gap:10px;color:#fff;font-weight:700}.contact-detail svg{width:20px;height:20px;fill:currentColor}
@media(max-width:1000px){.prefooter-grid{grid-template-columns:1fr}.about-prof{grid-template-columns:1fr 1fr}}
@media(max-width:650px){.prefooter-info{padding-top:50px}.about-prof{grid-template-columns:1fr}.prof-photo{min-height:330px}.about-copy,.contact-card{padding:28px}.footer-shell{padding-top:8px}}

.odl-feed-title{font-size:34px;line-height:1.1;margin:0 0 26px;letter-spacing:-1.5px}.odl-post-card{padding:0 0 28px;margin:0 0 28px;border-bottom:1px solid var(--line)}.odl-post-card:last-child{border-bottom:0;margin-bottom:0}.odl-post-card h2{font-size:28px;line-height:1.2;margin:0 0 10px}.odl-post-card h2 a:hover{color:var(--accent)}.odl-meta{font-size:13px;color:var(--muted);margin-bottom:14px}.odl-snippet{color:#555;line-height:1.75}.odl-read{display:inline-flex;margin-top:14px;font-weight:800;color:#1748c9}.odl-empty,.odl-loading{padding:55px 20px;text-align:center;color:var(--muted);font-weight:700}.odl-thumb{width:100%;max-height:360px;object-fit:cover;border-radius:18px;margin:0 0 18px}.odl-full-post h1{font-size:38px;line-height:1.12;margin:0 0 10px;letter-spacing:-1.5px}.odl-full-body{font-size:17px;line-height:1.8;color:#333}.odl-full-body img{border-radius:16px;margin:16px 0}.odl-full-body iframe{max-width:100%}.odl-full-body pre{overflow:auto}.odl-full-body a{color:#1748c9;text-decoration:underline}.odl-back{display:inline-flex;margin-bottom:22px;font-weight:800;color:#1748c9}

.odl-choice-head{margin-bottom:26px}.odl-choice-head h1{font-size:clamp(34px,5vw,58px);line-height:1;margin:0 0 10px;letter-spacing:-2px}.odl-choice-head p{color:var(--muted);margin:0}.odl-branches{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.odl-branch{background:#f8f8f7;border:1px solid var(--line);border-radius:24px;padding:28px;min-height:180px;position:relative;overflow:hidden;transition:.3s}.odl-branch:hover{transform:translateY(-5px);box-shadow:var(--shadow)}.odl-branch:after{display:none}.odl-branch-arrow{position:absolute;right:24px;bottom:20px;font-size:28px;line-height:1;font-weight:700}.odl-branch small{font-weight:900;letter-spacing:2px;color:var(--muted)}.odl-branch h2{font-size:28px;margin:28px 0 0}.odl-chapter-list{position:relative;padding-left:28px}.odl-chapter-list:before{content:'';position:absolute;left:17px;top:30px;bottom:30px;width:2px;background:#e4e4e4}.odl-chapter{position:relative;background:#fff;border:1px solid var(--line);border-radius:18px;padding:20px 22px;margin:0 0 18px;box-shadow:0 8px 22px rgba(17,19,24,.06);transition:.25s}.odl-chapter:hover{transform:translateX(4px);box-shadow:0 14px 30px rgba(17,19,24,.10)}.odl-num{position:absolute;left:-48px;top:16px;width:44px;height:44px;border-radius:50%;display:grid;place-items:center;background:#d93025;color:#fff;font-size:18px;font-weight:900;box-shadow:0 6px 14px rgba(217,48,37,.25)}.odl-chapter h2{font-size:25px;line-height:1.2;margin:0 0 12px;color:#2c4057}.odl-resource-links{display:grid;gap:8px}.odl-resource-links a{display:flex;align-items:center;gap:9px;color:#1677e8;font-weight:800;width:max-content;max-width:100%}.odl-folder{width:17px;height:13px;border-radius:2px;background:#1677e8;position:relative;display:inline-block;flex:0 0 auto}.odl-folder:before{content:'';position:absolute;left:1px;top:-4px;width:8px;height:5px;border-radius:2px 2px 0 0;background:#1677e8}.odl-breadcrumb{font-size:13px;color:var(--muted);margin-bottom:16px}.odl-breadcrumb a{color:#1748c9;font-weight:700}.odl-placeholder{padding:32px;border:1px dashed #ccd1d9;border-radius:18px;color:var(--muted);background:#fafafa}.odl-branches.three{grid-template-columns:repeat(3,minmax(0,1fr))}@media(max-width:760px){.odl-branches,.odl-branches.three{grid-template-columns:1fr}.odl-chapter-list{padding-left:22px}.odl-chapter-list:before{left:11px}.odl-num{left:-39px;width:38px;height:38px;font-size:15px}.odl-chapter{padding:18px}.odl-chapter h2{font-size:21px}}

.odl-contact-page{padding:34px 0 12px}.odl-contact-title{text-align:center;margin:0 0 54px;position:relative}.odl-contact-title .ghost{position:absolute;left:50%;top:50%;transform:translate(-50%,-56%);font-size:clamp(68px,11vw,150px);font-weight:300;letter-spacing:10px;color:rgba(17,19,24,.035);white-space:nowrap;pointer-events:none}.odl-contact-title h1{position:relative;display:inline-flex;align-items:center;gap:16px;margin:0;font-size:28px;letter-spacing:-.5px;text-transform:uppercase}.odl-contact-title h1:before,.odl-contact-title h1:after{content:'';width:34px;height:3px;background:#df4a46;border-radius:9px}.odl-contact-grid{display:grid;grid-template-columns:.72fr 1.48fr;gap:22px;align-items:stretch}.odl-contact-info,.odl-contact-formbox{background:#fff;border:1px solid var(--line);border-radius:12px;padding:30px;box-shadow:0 12px 34px rgba(17,19,24,.055)}.odl-contact-info{display:flex;flex-direction:column;gap:28px}.odl-contact-block h3,.odl-contact-formbox h2{margin:0 0 8px;padding-left:11px;border-left:3px solid #df3f3a;font-size:18px;line-height:1.2}.odl-contact-block p,.odl-contact-block a{display:block;margin:5px 0 0 14px;color:#3f4650;font-size:14px}.odl-contact-block a:hover{color:#d93025}.odl-contact-social{display:flex;gap:9px;margin:2px 0 0 14px}.odl-contact-social a{width:34px;height:34px;margin:0;border-radius:7px;background:#111318;color:#fff;display:grid;place-items:center;font-size:13px;font-weight:900;transition:.25s}.odl-contact-social a:hover{transform:translateY(-3px);background:#d93025;color:#fff}.odl-contact-formbox h2{font-size:25px;margin-bottom:28px}.odl-contact-form{display:grid;grid-template-columns:1fr 1fr;gap:18px}.odl-contact-form .full{grid-column:1/-1}.odl-contact-form input,.odl-contact-form textarea{width:100%;border:1px solid #d7d9dd;border-radius:7px;background:#fff;padding:14px 13px;font:inherit;color:#20242a;outline:none;transition:.25s}.odl-contact-form input:focus,.odl-contact-form textarea:focus{border-color:#df3f3a;box-shadow:0 0 0 3px rgba(223,63,58,.08)}.odl-contact-form textarea{min-height:130px;resize:vertical}.odl-contact-submit{grid-column:1/-1;width:max-content;border:0;border-radius:8px;background:#df3f3a;color:#fff;padding:13px 22px;font:inherit;font-weight:800;cursor:pointer;transition:.25s}.odl-contact-submit:hover{transform:translateY(-2px);background:#c92e2a;box-shadow:0 10px 24px rgba(217,48,37,.22)}.odl-contact-submit.odl-sent{background:#16a34a!important;color:#fff!important;box-shadow:0 10px 24px rgba(22,163,74,.28)!important;transform:none!important}.odl-contact-note{grid-column:1/-1;margin:0;color:var(--muted);font-size:12px}@media(max-width:850px){.odl-contact-grid{grid-template-columns:1fr}.odl-contact-title{margin-bottom:34px}}@media(max-width:560px){.odl-contact-page{padding-top:12px}.odl-contact-info,.odl-contact-formbox{padding:22px}.odl-contact-form{grid-template-columns:1fr}.odl-contact-form .full,.odl-contact-submit,.odl-contact-note{grid-column:1}.odl-contact-title .ghost{font-size:64px}}

.odl-about21{padding:22px 0 30px}.odl-about21-card{position:relative;overflow:hidden;display:grid;grid-template-columns:1.02fr .98fr;gap:30px;align-items:center;min-height:560px;padding:58px;border:1px solid #e8e8f4;border-radius:30px;background:linear-gradient(135deg,#fff 0%,#fff 58%,#f5f2ff 100%);box-shadow:0 25px 70px rgba(55,43,120,.10)}.odl-about21-card:before,.odl-about21-card:after{content:'';position:absolute;border-radius:50%;background:#ece8ff;z-index:0}.odl-about21-card:before{width:150px;height:150px;right:35%;top:-85px}.odl-about21-card:after{width:80px;height:80px;left:46%;bottom:-35px}.odl-about21-copy,.odl-about21-art{position:relative;z-index:1}.odl-about21-kicker{display:flex;align-items:center;gap:12px;color:#6454e8;font-size:12px;font-weight:900;letter-spacing:2px;text-transform:uppercase;margin-bottom:18px}.odl-about21-kicker:before{content:'';width:46px;height:3px;border-radius:4px;background:#6454e8}.odl-about21 h1{margin:0 0 18px;font-size:clamp(50px,7vw,88px);line-height:.92;letter-spacing:-4px;color:#2f2b74;text-transform:uppercase}.odl-about21 h2{margin:0 0 16px;font-size:clamp(24px,3vw,38px);line-height:1.15;letter-spacing:-1.2px;color:#111827}.odl-about21-desc{max-width:650px;margin:0;color:#737791;font-size:16px;line-height:1.85}.odl-about21-actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:28px}.odl-about21-btn{display:inline-flex;align-items:center;gap:10px;padding:14px 24px;border-radius:999px;background:linear-gradient(135deg,#6655f5,#4f3ce0);color:#fff!important;font-weight:900;box-shadow:0 12px 28px rgba(101,85,245,.28);transition:.25s}.odl-about21-btn:hover{transform:translateY(-3px);box-shadow:0 16px 34px rgba(101,85,245,.38)}.odl-about21-features{display:flex;gap:22px;flex-wrap:wrap;margin-top:34px}.odl-about21-feature{display:flex;align-items:center;gap:10px}.odl-about21-feature i{width:42px;height:42px;display:grid;place-items:center;border-radius:50%;background:#f0edff;color:#5e4ee7;font-style:normal;font-weight:900}.odl-about21-feature b{display:block;font-size:13px}.odl-about21-feature small{display:block;color:#8b8fa4;margin-top:2px}.odl-about21-art{min-height:430px;display:flex;align-items:center;justify-content:center}.odl-about21-blob{position:absolute;width:95%;height:86%;border-radius:48% 52% 45% 55% / 55% 45% 55% 45%;background:linear-gradient(145deg,#dcd7ff,#f0edff);transform:rotate(-4deg)}.odl-about21-photo{position:relative;width:90%;height:390px;object-fit:cover;border-radius:44% 56% 45% 55% / 56% 44% 56% 44%;box-shadow:0 24px 55px rgba(50,42,110,.18);border:8px solid rgba(255,255,255,.72)}.odl-about21-math{position:absolute;z-index:2;display:grid;place-items:center;width:58px;height:58px;border-radius:18px;background:#fff;box-shadow:0 12px 30px rgba(54,46,120,.14);font-size:20px;font-weight:900;color:#5d4ce6}.odl-about21-m1{left:2%;top:12%}.odl-about21-m2{right:0;top:20%;color:#e5a11a}.odl-about21-m3{right:5%;bottom:10%;color:#1fa7a0}.odl-about21-note{position:absolute;left:7%;bottom:5%;z-index:2;padding:10px 14px;border-radius:14px;background:#fff;color:#4d43b8;font-size:13px;font-weight:800;transform:rotate(-4deg);box-shadow:0 10px 25px rgba(54,46,120,.12)}@media(max-width:900px){.odl-about21-card{grid-template-columns:1fr;padding:38px 28px}.odl-about21-art{min-height:360px}.odl-about21-photo{height:330px}.odl-about21 h1{letter-spacing:-2px}}@media(max-width:560px){.odl-about21{padding-top:8px}.odl-about21-card{padding:30px 20px;border-radius:22px}.odl-about21 h1{font-size:48px}.odl-about21-art{min-height:300px}.odl-about21-photo{height:280px;width:96%}.odl-about21-features{gap:14px}.odl-about21-feature{width:100%}}


.odl-full-body .odl-course{max-width:900px;margin:20px auto;color:#172033;line-height:1.8}
.odl-full-body .odl-course-header{padding:35px 25px;border-radius:24px;background:linear-gradient(135deg,#f7f9ff,#fff);box-shadow:0 12px 35px rgba(0,0,0,.08);margin-bottom:30px;text-align:center}
.odl-full-body .odl-course-badge{display:inline-block;padding:7px 15px;border-radius:50px;background:#eef3ff;color:#1748c9;font-size:13px;font-weight:800;margin-bottom:12px}
.odl-full-body .odl-course h1{font-size:32px;margin:5px 0 10px;line-height:1.2}
.odl-full-body .odl-course h2{font-size:23px;margin:35px 0 15px;padding-left:14px;border-left:5px solid #e63946}
.odl-full-body .odl-box{background:#fff;border-radius:18px;padding:20px;margin:20px 0;box-shadow:0 8px 25px rgba(0,0,0,.07)}
.odl-full-body .odl-definition{border-left:5px solid #2563eb}.odl-full-body .odl-property{border-left:5px solid #16a34a}.odl-full-body .odl-example{border-left:5px solid #f59e0b}
.odl-full-body .odl-box-title{font-weight:800;font-size:17px;margin-bottom:8px}
.odl-full-body .odl-pdf-area{text-align:center;margin:45px 0 25px}
.odl-full-body a.odl-pdf-btn{position:relative;display:inline-flex;align-items:center;gap:12px;padding:16px 28px;border-radius:50px;background:linear-gradient(135deg,#e63946,#c1121f);color:#fff!important;text-decoration:none!important;font-weight:800;font-size:16px;box-shadow:0 10px 25px rgba(230,57,70,.30);transition:.3s ease;overflow:hidden}
.odl-full-body a.odl-pdf-btn:hover{transform:translateY(-5px) scale(1.03);box-shadow:0 16px 32px rgba(230,57,70,.40)}
.odl-full-body a.odl-pdf-btn.odl-pdf-waiting{cursor:wait;pointer-events:none;opacity:.92}
.odl-full-body a.odl-pdf-btn.odl-pdf-ready{background:linear-gradient(135deg,#22c55e,#15803d)!important;box-shadow:0 10px 30px rgba(34,197,94,.38)!important;animation:odlReadyPulse 1.5s infinite}
.odl-full-body a.odl-pdf-btn.odl-pdf-ready:hover{box-shadow:0 16px 36px rgba(34,197,94,.52)!important}
@keyframes odlReadyPulse{0%,100%{transform:scale(1)}50%{transform:scale(1.025)}}
.odl-full-body a.odl-pdf-btn:before{content:"";position:absolute;top:0;left:-100%;width:60%;height:100%;background:linear-gradient(90deg,transparent,rgba(255,255,255,.35),transparent);transform:skewX(-20deg);animation:odlShine 2.8s infinite}
.odl-full-body .odl-pdf-icon{font-size:22px;animation:odlDownload 1.5s infinite}
@keyframes odlShine{0%{left:-100%}45%,100%{left:150%}}
@keyframes odlDownload{0%,100%{transform:translateY(0)}50%{transform:translateY(4px)}}
@media(max-width:600px){.odl-full-body .odl-course{margin:8px 0}.odl-full-body .odl-course-header{padding:25px 15px}.odl-full-body .odl-course h1{font-size:25px}.odl-full-body .odl-course h2{font-size:20px}.odl-full-body a.odl-pdf-btn{padding:14px 20px;font-size:14px}}

.odl-essential-motion{position:relative;overflow:hidden;isolation:isolate;padding:96px 0}
.odl-essential-motion:before{content:'';position:absolute;inset:0;background:linear-gradient(180deg,rgba(247,249,252,.90),rgba(255,255,255,.82));z-index:-1}

.odl-essential-front{position:relative;z-index:2}
.odl-essential-front .section-head{background:rgba(255,255,255,.72);backdrop-filter:blur(9px);-webkit-backdrop-filter:blur(9px);padding:20px 24px;border-radius:22px;width:max-content;max-width:100%}
.odl-essential-front .resource{box-shadow:0 20px 55px rgba(17,19,24,.18)}
to{transform:translateX(-50%)}}
to{transform:translateX(0)}}
@media(max-width:700px){.odl-essential-motion{padding:72px 0}.odl-essential-front .section-head{padding:16px 18px}}

.odl-essential-motion .odl-shopify-card{
 opacity:0;
 transform:translateY(58px) scale(.92) rotateX(8deg);
 filter:blur(8px);
 transform-origin:50% 100%;
 transition:
   opacity .72s cubic-bezier(.16,1,.3,1),
   transform .9s cubic-bezier(.16,1,.3,1),
   filter .72s ease;
}
.odl-essential-motion.odl-resources-in .odl-shopify-card{
 opacity:1;
 transform:translateY(0) scale(1) rotateX(0);
 filter:blur(0);
}
.odl-essential-motion.odl-resources-in .odl-delay-1{transition-delay:.05s}
.odl-essential-motion.odl-resources-in .odl-delay-2{transition-delay:.55s}
.odl-essential-motion.odl-resources-in .odl-delay-3{transition-delay:1.05s}
.odl-essential-motion.odl-resources-in .odl-delay-4{transition-delay:1.55s}
.odl-essential-motion .odl-shopify-card b,
.odl-essential-motion .odl-shopify-card span{
 transition:transform .65s cubic-bezier(.16,1,.3,1),opacity .65s ease;
}
.odl-essential-motion:not(.odl-resources-in) .odl-shopify-card b,
.odl-essential-motion:not(.odl-resources-in) .odl-shopify-card span{
 transform:translateY(16px);
 opacity:0;
}
.odl-essential-motion.odl-resources-in .odl-shopify-card b,
.odl-essential-motion.odl-resources-in .odl-shopify-card span{
 transform:translateY(0);
 opacity:1;
}
@media(prefers-reduced-motion:reduce){
 .odl-essential-motion .odl-shopify-card{opacity:1!important;transform:none!important;filter:none!important;transition:none!important}
 .odl-essential-motion .odl-shopify-card b,.odl-essential-motion .odl-shopify-card span{opacity:1!important;transform:none!important;transition:none!important}
}

.odl-back-wrap{margin:0 0 18px}
.odl-back-btn{display:inline-flex;align-items:center;gap:9px;padding:10px 16px;border:1px solid #1677e8;border-radius:999px;background:#1677e8;color:#fff;font-weight:800;box-shadow:0 8px 22px rgba(22,119,232,.22);cursor:pointer;transition:transform .2s ease,box-shadow .2s ease,background .2s ease}
.odl-back-btn:hover{transform:translateX(-3px);background:#0f66cc;box-shadow:0 11px 28px rgba(22,119,232,.32)}
.odl-back-arrow{font-size:20px;line-height:1}


.odl-level-cta{padding:34px 0 42px;background:var(--paper)}
.odl-level-cta-head{text-align:center;margin-bottom:24px}
.odl-level-cta-head>span{display:inline-block;font-size:11px;font-weight:900;letter-spacing:2.5px;color:#737986;margin-bottom:8px}
.odl-level-cta-head h2{margin:0;font-size:clamp(34px,4vw,52px);letter-spacing:-2px;line-height:1}
.odl-level-cta-head p{margin:10px 0 0;color:var(--muted)}
.odl-level-cta-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.odl-level-cta-card{position:relative;min-height:170px;padding:26px;border:1px solid var(--line);border-radius:24px;background:#fff;box-shadow:0 12px 35px rgba(17,19,24,.06);transition:transform .3s ease,box-shadow .3s ease}
.odl-level-cta-card:hover{transform:translateY(-6px);box-shadow:0 20px 50px rgba(17,19,24,.12)}
.odl-level-cta-card small{display:block;color:#737986;font-weight:900;letter-spacing:2px}
.odl-level-cta-card b{display:block;margin-top:30px;font-size:30px;line-height:1}
.odl-level-cta-card span{position:absolute;right:25px;bottom:20px;font-size:28px}
@media(max-width:760px){.odl-level-cta-grid{grid-template-columns:1fr}.odl-level-cta-card{min-height:145px}}


.odl-contact-social a{font-size:0}
.odl-contact-social svg{width:18px;height:18px;fill:currentColor;display:block}

.odl-level-cta .odl-level-anim{opacity:0;transform:translateY(58px) scale(.92) rotateX(8deg);filter:blur(8px);transform-origin:50% 100%;transition:opacity .5s cubic-bezier(.16,1,.3,1),transform .5s cubic-bezier(.16,1,.3,1),filter .5s ease}
.odl-level-cta.odl-levels-in .odl-level-anim{opacity:1;transform:translateY(0) scale(1) rotateX(0);filter:blur(0)}
.odl-level-cta.odl-levels-in .odl-level-delay-1{transition-delay:.05s}
.odl-level-cta.odl-levels-in .odl-level-delay-2{transition-delay:.55s}
.odl-level-cta.odl-levels-in .odl-level-delay-3{transition-delay:1.05s}
@media(prefers-reduced-motion:reduce){.odl-level-cta .odl-level-anim{opacity:1!important;transform:none!important;filter:none!important;transition:none!important}}


.odl-level-cta{background:linear-gradient(135deg,#eaf3ff 0%,#f5f9ff 55%,#e6f0ff 100%)}
.odl-level-cta-head>span{color:#1677e8}
.odl-level-cta-head h2{color:#15395f}
.odl-level-cta-card{border-color:#cfe2fb;background:linear-gradient(145deg,#ffffff,#eef6ff);box-shadow:0 14px 36px rgba(22,119,232,.10)}
.odl-level-cta-card:hover{border-color:#9bc7f5;box-shadow:0 22px 52px rgba(22,119,232,.18)}
.odl-level-cta-card small{color:#1677e8}
.odl-level-cta-card b{color:#15395f}
.odl-level-cta-card span{color:#1677e8}


.odl-top-ad-space{width:min(1320px,96%);margin:104px auto 0;padding:12px 0 4px}
.odl-top-ad-inner{min-height:110px;width:100%;display:flex;align-items:center;justify-content:center;border-radius:18px}
@media(max-width:900px){.odl-top-ad-space{margin-top:92px}.odl-top-ad-inner{min-height:90px}}

body.script:
