(function(){
  var box=document.getElementById('odl-posts'); if(!box) return;



  function esc(x){var d=document.createElement('div');d.textContent=x||'';return d.innerHTML;}
  function strip(x){var d=document.createElement('div');d.innerHTML=x||'';return (d.textContent||d.innerText||'').replace(/\s+/g,' ').trim();}
  function labelUrl(label){return '/search/label/'+encodeURIComponent(label);}
  var path=decodeURIComponent(location.pathname);
  var m=path.match(/\/search\/label\/([^/?#]+)/i);
  var label=m?m[1].replace(/\+/g,' '):'';
  if(!document.querySelector('.odl-back-wrap') && label){
    var bw=document.createElement('div');
    bw.className='odl-back-wrap';
    bw.innerHTML='<button class="odl-back-btn" type="button" onclick="history.back()"><span class="odl-back-arrow">←</span> Retour</button>';
    box.parentNode.insertBefore(bw,box);
  }

  var odlRoute='';
  try{odlRoute=(new URLSearchParams(location.search).get('odl')||'').toLowerCase();}catch(err){}

