    var html='<div class="odl-choice-head"><h1>'+esc(level)+'</h1><p>Choisissez votre filière pour afficher les chapitres.</p></div><div class="'+cls+'">';
    list.forEach(function(b){html+='<a class="odl-branch" href="'+labelUrl(b.label)+'"><small>'+esc(level)+'</small><h2>'+esc(b.name)+'</h2><span class="odl-branch-arrow">→</span></a>';});
    box.innerHTML=html+'</div>';
  }
  function renderChapters(key){
