    list.forEach(function(c,i){var n=String(i+1).padStart(2,'0');html+='<article class="odl-chapter"><span class="odl-num">'+n+'</span><h2>'+esc(c.title)+'</h2><div class="odl-resource-links"><a href="'+labelUrl(c.base+'-Cours')+'"><span class="odl-folder"></span>Cours</a><a href="'+labelUrl(c.base+'-Exercices')+'"><span class="odl-folder"></span>Exercices</a></div></article>';});
    box.innerHTML=html+'</div>';
  }

