  if(label==='Devoirs'){
    box.innerHTML='<div class="odl-choice-head"><h1>Devoirs</h1><p>Choisissez votre niveau.</p></div><div class="odl-branches three"><a class="odl-branch" href="/search/label/Devoirs-TCS"><small>DEVOIRS</small><h2>TCS</h2><span class="odl-branch-arrow">→</span></a><a class="odl-branch" href="/search/label/Devoirs-1BAC"><small>DEVOIRS</small><h2>1BAC</h2><span class="odl-branch-arrow">→</span></a><a class="odl-branch" href="/search/label/Devoirs-2BAC"><small>DEVOIRS</small><h2>2BAC</h2><span class="odl-branch-arrow">→</span></a></div>';
    return;
  }
  var devoirRoutes={
    'Devoirs-TCS':[{name:'Sciences',key:'TCS-Sciences'},{name:'Lettres',key:'TCS-Lettres'}],
    'Devoirs-1BAC':[{name:'Sciences',key:'1BAC-Sciences'},{name:'SMA',key:'1BAC-SMA'},{name:'Lettres',key:'1BAC-Lettres'}],
    'Devoirs-2BAC':[{name:'PC & SVT',key:'2BAC-PC-SVT'},{name:'SMA',key:'2BAC-SMA'},{name:'Lettres',key:'2BAC-Lettres'}]
  };
  if(devoirRoutes[label]){
    var ds=devoirRoutes[label];
    var dtitle=label.replace('Devoirs-','');
    var dh='<div class="odl-choice-head"><h1>Devoirs • '+esc(dtitle)+'</h1><p>Choisissez votre filière.</p></div><div class="odl-branches three">';
    ds.forEach(function(b){dh+='<a class="odl-branch" href="'+labelUrl('Devoirs-'+b.key)+'"><small>DEVOIRS</small><h2>'+esc(b.name)+'</h2><span class="odl-branch-arrow">→</span></a>';});
    box.innerHTML=dh+'</div>';
    return;
