    box.innerHTML='<div class="odl-choice-head"><h1>Devoirs • '+esc(pretty)+'</h1><p>Choisissez le semestre.</p></div><div class="odl-branches"><a class="odl-branch" href="'+labelUrl('Devoirs-'+dk+'-S1')+'"><small>SEMESTRE</small><h2>Semestre 1</h2><span class="odl-branch-arrow">→</span></a><a class="odl-branch" href="'+labelUrl('Devoirs-'+dk+'-S2')+'"><small>SEMESTRE</small><h2>Semestre 2</h2><span class="odl-branch-arrow">→</span></a></div>';
