  // Chaque nombre = nombre d'exemples du devoir correspondant.
  // Exemple : S1:[4,4,4,4] = 4 devoirs, chacun avec 4 exemples.
  // Exemple : S1:[3,4,2,4] = D1 a 3 exemples, D2 en a 4, D3 en a 2, D4 en a 4.
  // Pour supprimer le Devoir 04 complet : S1:[4,4,4]
  var devoirsConfig={
    'TCS-Sciences': {S1:[4,4,4,4], S2:[4,4,4,4]},
    'TCS-Lettres':  {S1:[4,4,4,4], S2:[4,4,4,4]},

    '1BAC-Sciences':{S1:[4,4,4,4], S2:[4,4,4,4]},
    '1BAC-SMA':     {S1:[4,4,4,4], S2:[4,4,4,4]},
    '1BAC-Lettres': {S1:[4,4,4,4], S2:[4,4,4,4]},

    '2BAC-PC-SVT':  {S1:[4,4,4,4], S2:[4,4,4,4]},
    '2BAC-SMA':     {S1:[4,4,4,4], S2:[4,4,4,4]},
    '2BAC-Lettres': {S1:[4,4,4,4], S2:[4,4,4,4]}
  };

