    var cfg=devoirsConfig[base];
    var counts=cfg ? cfg['S'+sem] : [4,4,4,4];
    var dh2='<div class="odl-choice-head"><h1>'+esc(prettyBase)+' • Semestre '+sem+'</h1><p>Les exemples sont affichés directement sous chaque devoir.</p></div><div class="odl-chapter-list">';
