  window.odlxyzFeed=function(data){
    var entries=(data&&data.feed&&data.feed.entry)||[];
    var heading=label||'Articles récents';
    var html='<h1 class="odl-feed-title">'+esc(heading.replace(/-/g,' '))+'</h1>';
    if(!entries.length){box.innerHTML=html+'<div class="odl-empty">Aucun article trouvé dans cette catégorie.</div>';return;}
    entries.forEach(function(e){
      var title=e.title&&e.title.$t||'Article'; var link='#'; (e.link||[]).forEach(function(l){if(l.rel==='alternate')link=l.href;});
      var body=(e.content&&e.content.$t)||(e.summary&&e.summary.$t)||''; var sn=strip(body); if(sn.length>260) sn=sn.slice(0,260)+'…';
      var date=e.published&&e.published.$t?new Date(e.published.$t).toLocaleDateString('fr-FR',{year:'numeric',month:'long',day:'numeric'}):'';
      var thumb=e.media$thumbnail&&e.media$thumbnail.url?e.media$thumbnail.url.replace(/s72-c/,'s1200'):'';
      html+='<article class="odl-post-card">'+(thumb?'<img class="odl-thumb" src="'+thumb+'" alt="" loading="lazy"/>':'')+'<h2><a href="'+link+'">'+esc(title)+'</a></h2><div class="odl-meta">'+esc(date)+'</div><div class="odl-snippet">'+esc(sn)+'</div><a class="odl-read" href="'+link+'">Lire l’article →</a></article>';
    }); box.innerHTML=html;
  };
  // PDF: first click starts a 10-second countdown; second click opens the PDF.
  document.addEventListener('click',function(ev){
    var btn=ev.target.closest?ev.target.closest('a.odl-pdf-btn'):null;
    if(!btn) return;
    if(btn.getAttribute('data-odl-ready')==='1') return;
    ev.preventDefault();
