(function(){
  function twoToneTitles(){
    var nodes=document.querySelectorAll('.odl-section-title,.odl-page-title,.odl-hierarchy-title');
    for(var i=0;i<nodes.length;i++){
      var el=nodes[i];
      if(el.getAttribute('data-odlMotion-title')) continue;
      var t=(el.textContent||'').trim();
      var parts=t.split(/\s*(?:\||—)\s*/);
      if(parts.length===2){
        el.innerHTML='<span class="odl-title-dark">'+parts[0]+'</span><span class="odl-title-light">'+parts[1]+'</span>';
      }
      el.setAttribute('data-odlMotion-title','1');
    }
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',twoToneTitles);
  else twoToneTitles();
})();
//

//
(function(){
  function odlV301Style(){
    var heads=document.querySelectorAll('.odl-choice-head h1');
    for(var i=0;i<heads.length;i++){
      var h=heads[i];
      if(h.getAttribute('data-odlAnim')) continue;
      var raw=(h.textContent||'').trim();
      var parts=raw.split(/\s*•\s*/);
      if(parts.length>1){
        h.innerHTML='<span class="odl-title-dark">'+parts[0]+'</span><span class="odl-title-light">'+parts.slice(1).join(' • ')+'</span>';
      }else{
        h.innerHTML='<span class="odl-title-dark">'+raw+'</span>';
      }
      h.setAttribute('data-odlAnim','1');
    }
  }
  var obs=new MutationObserver(odlV301Style);
  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',function(){
      odlV301Style();
      var b=document.getElementById('odl-posts'); if(b)obs.observe(b,{childList:true,subtree:true});
    });
  }else{
    odlV301Style();
    var b=document.getElementById('odl-posts'); if(b)obs.observe(b,{childList:true,subtree:true});
  }
})();
