(function(){
  function initResourceEntrance(){
    var section=document.querySelector('.odl-essential-motion');
    if(!section) return;
    if(!('IntersectionObserver' in window)){section.classList.add('odl-resources-in');return;}
    var io=new IntersectionObserver(function(entries){
      entries.forEach(function(entry){
        if(entry.isIntersecting){
          section.classList.add('odl-resources-in');
          io.disconnect();
        }
      });
    },{threshold:.24});
    io.observe(section);
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',initResourceEntrance);
  else initResourceEntrance();
})();
//

//
(function(){
  function initLevelCards(){
    var section=document.querySelector('.odl-level-cta');
    if(!section) return;
    if(!('IntersectionObserver' in window)){section.classList.add('odl-levels-in');return;}
    var io=new IntersectionObserver(function(entries){
      if(entries[0].isIntersecting){section.classList.add('odl-levels-in');io.disconnect();}
    },{threshold:.24});
    io.observe(section);
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',initLevelCards);
  else initLevelCards();
})();
